CREATE TABLE daily_checks (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, check_date DATE NOT NULL, result VARCHAR(20) NOT NULL, notes TEXT NOT NULL, checked_by BIGINT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(device_id,check_date), FOREIGN KEY(device_id) REFERENCES devices(id), FOREIGN KEY(checked_by) REFERENCES users(id), INDEX(check_date,result));
